const setAttributeIndexableCascade = `-- name: SetAttributeIndexableCascade :one
UPDATE catalog_attributes
SET is_indexable = $2,
    updated_at   = NOW()
WHERE id = $1
RETURNING id, slug, name, input_type, unit, value_required, filterable, searchable, is_public, sort_order, metadata, private_metadata, created_at, updated_at, default_value, facet_collapsed, is_indexable, h1_position, synapse_track, auto_segment, relationship_target
`

type SetAttributeIndexableCascadeParams struct {
	ID          uuid.UUID `json:"id"`
	IsIndexable bool      `json:"is_indexable"`
}

// Toggles the master indexable flag on the attribute - for selectable attributes the cascade into AttributeValue is done in the separate statement below - kept here together so the service can run them in one transaction - scalar attributes have no per-row indexability: the attribute flag is read directly by the indexer
func (q *Queries) SetAttributeIndexableCascade(ctx context.Context, arg SetAttributeIndexableCascadeParams) (Attribute, error) {
	row := q.db.QueryRowContext(ctx, setAttributeIndexableCascade, arg.ID, arg.IsIndexable)
	var i Attribute
	err := row.Scan(
		&i.ID,
		&i.Slug,
		&i.Name,
		&i.InputType,
		&i.Unit,
		&i.ValueRequired,
		&i.Filterable,
		&i.Searchable,
		&i.IsPublic,
		&i.SortOrder,
		&i.Metadata,
		&i.PrivateMetadata,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DefaultValue,
		&i.FacetCollapsed,
		&i.IsIndexable,
		&i.H1Position,
		&i.SynapseTrack,
		&i.AutoSegment,
		&i.RelationshipTarget,
	)
	return i, err
}

